Certainly! Below is a complex smart contract designed for a decentralized voting system. This contract includes features such as voter registration, candidate registration, voting, and result tallying, ensuring transparency and security.

```solidity
pragma solidity ^0.8.0;

contract DecentralizedVoting {
    struct Voter {
        bool registered;
        bool voted;
        uint256 vote;
    }

    struct Candidate {
        string name;
        uint256 voteCount;
    }

    address public admin;
    mapping(address => Voter) public voters;
    Candidate[] public candidates;
    bool public votingEnded;

    event VoterRegistered(address indexed voter);
    event VoterVoted(address indexed voter, uint256 indexed candidate);
    event CandidateRegistered(string name);
    event VotingEnded();

    modifier onlyAdmin() {
        require(msg.sender == admin, "Only admin can call this function.");
        _;
    }

    modifier onlyRegisteredVoter() {
        require(voters[msg.sender].registered, "Only registered voters can call this function.");
        _;
    }

    modifier votingNotEnded() {
        require(!votingEnded, "Voting has already ended.");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function registerVoter(address _voter) public onlyAdmin {
        require(!voters[_voter].registered, "Voter is already registered.");
        voters[_voter].registered = true;
        emit VoterRegistered(_voter);
    }

    function registerCandidate(string memory _name) public onlyAdmin {
        candidates.push(Candidate({name: _name, voteCount: 0}));
        emit CandidateRegistered(_name);
    }

    function vote(uint256 _candidateIndex) public onlyRegisteredVoter votingNotEnded {
        require(_candidateIndex < candidates.length, "Invalid candidate index.");
        require(!voters[msg.sender].voted, "Voter has already voted.");

        voters[msg.sender].vote = _candidateIndex;
        voters[msg.sender].voted = true;

        candidates[_candidateIndex].voteCount += 1;

        emit VoterVoted(msg.sender, _candidateIndex);
    }

    function endVoting() public onlyAdmin {
        votingEnded = true;
        emit VotingEnded();
    }

    function getCandidate(uint256 _candidateIndex) public view returns (string memory, uint256) {
        require(_candidateIndex < candidates.length, "Invalid candidate index.");
        return (candidates[_candidateIndex].name, candidates[_candidateIndex].voteCount);
    }

    function getVoter(address _voter) public view returns (bool, bool, uint256) {
        return (voters[_voter].registered, voters[_voter].voted, voters[_voter].vote);
    }
}
```

This smart contract includes the following features:
1. Voter registration: Only the admin can register voters.
2. Candidate registration: Only the admin can register candidates.
3. Voting: Registered voters can vote for candidates, but only once.
4. Voting end: The admin can end the voting process.
5. Event logging: Events are emitted for voter registration, voting, candidate registration, and voting end.

This contract ensures transparency, security, and ease of use for a decentralized voting system.

